  ('58d36714-f668-4606-ac97-0d17968415a0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संयोग से उसी वक़्त एक कटा हुआ कनकोआ हमारे ऊपर से गुज़रा। उसकी डोर लटक रही थी। लड़कों का एक गोल पीछे-पीछे दौड़ा चला आता था। भाई साहब लंबे हैं ही। उछलकर उसकी डोर पकड़ ली और बेतहाशा हॉस्टल की तरफ़ दौड़े। मैं पीछे-पीछे दौड़ रहा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3f423163-48f2-47ce-b549-4e098ee8e378', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$संयोग से उसी वक़्त एक कटा हुआ कनकोआ हमारे ऊपर से गुज़रा। उसकी डोर लटक रही थी। लड़कों का एक गोल पीछे-पीछे दौड़ा चला आता था। भाई साहब लंबे हैं ही। उछलकर उसकी डोर पकड़ ली और बेतहाशा हॉस्टल की तरफ़ दौड़े। मैं पीछे-पीछे दौड़ रहा था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f3945ecf-6699-4db8-873a-b4890ef76e7b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे भाई साहब मुझसे पाँच साल बड़े, लेकिन केवल तीन दरजे आगे। उन्होंने भी उसी उम्र में पढ़ना शुरू किया था, जब मैंने शुरू किया लेकिन तालीम जैसे महत्त्व के मामले में वह जल्दबाजी से काम लेना पसंद न करते थे। इस भवन की बुनियाद खूब मजबूत डालना चाहते थे, जिस पर आलीशान महल बन सके। एक साल का काम दो साल में करते थे। कभी-कभी तीन साल भी लग जाते थे। बुनियाद ही पुख्ता न हो, तो मकान कैसे पायेदार बने।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('6927bb51-152d-488d-be99-710876bd6aa1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं छोटा था, वह बड़े थे। मेरी उम्र नौ साल की थी, वह चौदह साल के थे। उन्हें मेरी तम्बीह और निगरानी का पूरा और जन्मसिद्ध अधिकार था और मेरी शालिनता इसी में थी कि उनके हुक्म को कानून समझूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a97dc269-b956-4c2c-9a8e-cd4e46cd992c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह स्वभाव से बड़े अध्ययनशील थे। हरदम किताब खोले बैठे रहते और शायद दिमाग को आराम देने के लिए कभी कॉपी पर, किताब के हाशियों पर चिड़ियों, कुत्तों, बिल्लियों की तस्वीरें बनाया करते थे। कभी-कभी एक ही नाम या शब्द या वाक्य दस-बीस बार लिख डालते। कभी एक शेर को बार-बार सुंदर अक्षरों में नकल करते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('eca7c9ae-3e57-4cd5-b6f8-25babbedc0c1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी ऐसी शब्द-रचना करते, जिसमें न कोई अर्थ होता, न कोई सामंजस्य। मसलन एक बार उनकी कॉपी पर मैंने यह इबारत देखी—स्पेशल, अमीना, भाइयों-भाइयों, दरअसल, भाई-भाई। राधेश्याम, श्रीयुत राधेश्याम, एक घंटे तक—इसके बाद एक आदमी का चेहरा बना हुआ था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3b888690-83e6-4636-a29e-f9b6760b70f6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने बहुत चेष्टा की कि इस पहेली का कोई अर्थ निकालूँ, लेकिन असफल रहा। और उनसे पूछने का साहस न हुआ। वह नौवीं जमात में थे, मैं पाँचवीं में। उनकी रचनाओं को समझना मेरे लिए छोटा मुँह बड़ी बात थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
