  ('775e30e8-1b9e-469a-9cd8-1b85d8e6d43e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं छोटा था, वह बड़े थे। मेरी उम्र नौ साल की थी, वह चौदह साल के थे। उन्हें मेरी तम्बीह और निगरानी का पूरा और जन्मसिद्ध अधिकार था और मेरी शालिनता इसी में थी कि उनके हुक्म को कानून समझूँ। वह स्वभाव से बड़े अध्ययनशील थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
