  ('f622bf7f-2abb-4945-abb2-43970cc54b1f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने बहुत चेष्टा की कि इस पहेली का कोई अर्थ निकालूँ, लेकिन असफल रहा। और उनसे पूछने का साहस न हुआ। वह नौवीं जमात में थे, मैं पाँचवीं में। उनकी रचनाओं को समझना मेरे लिए छोटा मुँह बड़ी बात थी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a3665d9b-d1e8-4f2b-b996-dad302ced65c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे भाई साहब मुझसे पाँच साल बड़े, लेकिन केवल तीन दरजे आगे। उन्होंने भी उसी उम्र में पढ़ना शुरू किया था, जब मैंने शुरू किया लेकिन तालीम जैसे महत्त्व के मामले में वह जल्दबाजी से काम लेना पसंद न करते थे। इस भवन की बुनियाद खूब मजबूत डालना चाहते थे, जिस पर आलीशान महल बन सके। एक साल का काम दो साल में करते थे। कभी-कभी तीन साल भी लग जाते थे। बुनियाद ही पुख्ता न हो, तो मकान कैसे पायेदार बने। मैं छोटा था, वह बड़े थे। मेरी उम्र नौ साल की थी, वह चौदह साल के थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('6ca31634-6771-4716-961e-ba77e1b12b67', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उन्हें मेरी तम्बीह और निगरानी का पूरा और जन्मसिद्ध अधिकार था और मेरी शालिनता इसी में थी कि उनके हुक्म को कानून समझूँ। वह स्वभाव से बड़े अध्ययनशील थे। हरदम किताब खोले बैठे रहते और शायद दिमाग को आराम देने के लिए कभी कॉपी पर, किताब के हाशियों पर चिड़ियों, कुत्तों, बिल्लियों की तस्वीरें बनाया करते थे। कभी-कभी एक ही नाम या शब्द या वाक्य दस-बीस बार लिख डालते। कभी एक शेर को बार-बार सुंदर अक्षरों में नकल करते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('2a59afe2-cb3d-453f-bc77-a6c19d8ee802', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा जी पढ़ने में बिल्कुल न लगता था। एक घंटा भी किताब लेकर बैठना पहाड़ था। मौका पाते ही हॉस्टल से निकलकर मैदान में आ जाता और कभी कंकड़ियाँ उछालता, कभी कागज़ की तितलियाँ उड़ाता और कहीं कोई साथी मिल गया, तो पूछना ही क्या। कभी चारदीवारी पर चढ़कर नीचे कूद रहे हैं। कभी फाटक पर सवार, उसे आगे-पीछे चलाते हुए मोटरकार का आनंद उठा रहे हैं$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('94bfc9f8-ff97-4651-b003-dd5fd790d156', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन कमरे में आते ही भाई साहब का वह रुद्र-रूप देखकर प्राण सूख जाते। उनका पहला सवाल यह होता—'कहाँ थे?' हमेशा यही सवाल, इसी ध्वनि में हमेशा पूछा जाता था और इसका जवाब मेरे पास केवल मौन था। न जाने मेरे मुँह से यह बात क्यों न निकलती कि ज़रा बाहर खेल रहा था। मेरा मौन कह देता था कि मुझे अपना अपराध स्वीकार है$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('1802544a-805d-468a-9640-0880cd3a0874', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और भाई साहब के लिए उसके सिवा और कोई इलाज न था कि स्नेह और रोष से मिले हुए शब्दों में मेरा सत्कार करें। 'इस तरह अंग्रेज़ी पढ़ोगे, तो ज़िंदगी-भर पढ़ते रहोगे और एक हर्फ़ न आएगा। अंग्रेज़ी पढ़ना कोई हँसी-खेल नहीं है कि जो चाहे, पढ़ ले, नहीं ऐरा-गैरा नत्थू-खैरा सभी अंग्रेज़ी के विद्वान हो जाते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('a141ae3b-d93d-4eb6-ada2-b9f4948a9a2b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यहाँ रात-दिन आँखें फोड़नी पड़ती हैं और खून जलाना पड़ता है, तब कहीं यह विद्या आती है। और आती क्या है, हाँ कहने को आ जाती है। बड़े-बड़े विद्वान भी शुद्ध अंग्रेज़ी न लिख सकते, बोलना तो दूर रहा। और मैं कहता हूँ, तुम कितने घोंघा हो कि मुझे देखकर भी सबक नहीं लेते।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('dcd320ad-2dcd-492b-9696-3288d9f02c31', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं कितनी मेहनत करता हूँ, यह तुम अपनी आँखों से देखते हो, अगर नहीं देखते, तो यह तुम्हारी आँखों का कसूर है, तुम्हारी बुद्धि का कसूर है। इतने मेले-तमाशे होते हैं, मुझे तुमने कभी देखने जाते देखा है? रोज़ ही क्रिकेट और हॉकी मैच होते हैं। मैं पास नहीं फटकता। हमेशा पढ़ता रहता हूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c592eca3-13fe-45ba-9565-4d9e39dee113', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस पर भी एक-एक दरजे में दो-दो, तीन-तीन साल पड़ा रहता हूँ, फिर भी तुम कैसे आशा करते हो कि तुम यों खेल-कूद में वक़्त गँवाकर पास हो जाओगे? मुझे तो दो ही तीन साल लगते हैं, तुम उम्र-भर इसी दरजे में पड़े सड़ते रहोगे? अगर तुम्हें इस तरह उम्र गँवानी है, तो बेहतर है, घर चले जाओ और मज़े से गुल्ली-डंडा खेलो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('bfc1b91c-4a71-4f86-84b8-e4512bce7ed4', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दादा की गाढ़ी कमाई के रुपये क्यों बर्बाद करते हो?' मैं यह लताड़ सुनकर आँसू बहाने लगता। जवाब ही क्या था। अपराध तो मैंने किया, लताड़ कौन सहे? भाई साहब उपदेश की कला में निपुण थे। ऐसी-ऐसी लगती बातें कहते, ऐसे-ऐसे सूक्ति-बाण चलाते कि मेरे जिगर के टुकड़े-टुकड़े हो जाते और हिम्मत टूट जाती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('eb6d590e-0e7a-43d9-b0fb-ad29e951959b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस तरह जान तोड़कर मेहनत करने की शक्ति मैं अपने में न पाता था और उस निराशा में ज़रा देर के लिए मैं सोचने लगता—'क्यों न घर चला जाऊँ? जो काम मेरे बूते के बाहर है, उसमें हाथ डालकर क्यों अपनी ज़िंदगी खराब करूँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('16324260-7f1a-4f45-ba82-193bf41db31a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे अपना मूर्ख रहना मंजूर था, लेकिन उतनी मेहनत से मुझे तो चक्कर आ जाता था, लेकिन घंटे-दो घंटे के बाद निराशा के बादल फट जाते और मैं इरादा करता कि आगे से खूब जी लगाकर पढूँगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('e6b89a1e-f42e-466d-bd45-f895aa5e26be', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चटपट एक टाइम-टेबिल बना डालता। बिना पहले से नक़्शा बनाए कोई स्कीम तैयार किए काम कैसे शुरू करूँ। टाइम-टेबिल में खेल-कूद की मद बिल्कुल उड़ जाती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('3018eeb1-8951-48f2-86a4-59e9a4d3afae', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रातःकाल छह बजे उठना, मुँह-हाथ धो, नाश्ता कर, पढ़ने बैठ जाना। छह से आठ तक अंग्रेज़ी, आठ से नौ तक हिसाब$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('0b3202d4-20aa-4191-a636-6208b92c9860', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा जी पढ़ने में बिल्कुल न लगता था। एक घंटा भी किताब लेकर बैठना पहाड़ था। मौका पाते ही हॉस्टल से निकलकर मैदान में आ जाता और कभी कंकड़ियाँ उछालता, कभी कागज़ की तितलियाँ उड़ाता और कहीं कोई साथी मिल गया, तो पूछना ही क्या। कभी चारदीवारी पर चढ़कर नीचे कूद रहे हैं। कभी फाटक पर सवार, उसे आगे-पीछे चलाते हुए मोटरकार का आनंद उठा रहे हैं, लेकिन कमरे में आते ही भाई साहब का वह रुद्र-रूप देखकर प्राण सूख जाते। उनका पहला सवाल यह होता—'कहाँ थे?' हमेशा यही सवाल, इसी ध्वनि में हमेशा पूछा जाता था और इसका जवाब मेरे पास केवल मौन था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('91bcc440-4b6f-4bb8-8614-c730d6483593', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नौ से साढ़े नौ तक इतिहास, फिर भोजन और स्कूल। साढ़े तीन बजे स्कूल से वापस होकर आधा घंटा आराम, चार से पाँच तक भूगोल, पाँच से छह तक ग्रामर, आधा घंटा हॉस्टल के सामने ही टहलना, साढ़े छह से सात तक अंग्रेजी कंपोजीशन, फिर भोजन करके आठ से नौ तक अनुवाद, नौ से दस तक हिंदी, दस से ग्यारह तक विविध-विषय, फिर विश्राम। मगर टाइम-टेबिल बना लेना एक बात है, उस पर अमल करना दूसरी बात। पहले ही दिन उसकी अवहेलना शुरू हो जाती।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('f68a0d5e-581e-45af-866d-6bd836621dda', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैदान की वह सुखद हरियाली, हवा के हलके-हलके झोंके, फुटबॉल की वह उछल-कूद, कबड्‌डी के वह दाँव-घात, वॉलीबॉल की वह तेजी और फुर्ती, मुझे अज्ञात और अनिवार्य रूप से खींच ले जाती और वहाँ जाते ही मैं सब कुछ भूल जाता। वह जानलेवा टाइम-टेबिल, वह आँखफोड़ पुस्तकें, किसी की याद न रहती और भाई साहब को नसीहत और फजीहत का अवसर मिल जाता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ae617263-5ce7-42e4-a6c1-9b106598e6ef', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं उनके साये से भागता, उनकी आँखों से दूर रहने की चेष्टा करता, कमरे में इस तरह दबे पाँव आता कि उन्हें खबर न हो। उनकी नजर मेरी ओर उठी और मेरे प्राण निकले। हमेशा सिर पर एक नंगी तलवार-सी लटकती मालूम होती। फिर भी जैसे मौत और विपत्ति के बीच भी आदमी मोह और माया के बंधन में जकड़ा रहता है, मैं फटकार और घुड़कियाँ खाकर भी खेल-कूद का तिरस्कार न कर सकता था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6e88c27a-8e20-406d-bf9e-41c1618a3545', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सालाना इम्तिहान हुआ। भाई साहब फेल हो गए, मैं पास हो गया और दरजे में प्रथम आया। मेरे और उनके बीच में केवल दो साल का अंतर रह गया। जी में आया, भाई साहब को आड़े हाथों लूँ—'आपकी वह घोर तपस्या कहाँ गई? मुझे देखिए, मजे से खेलता भी रहा और दरजे में अव्वल भी हूँ।' लेकिन वह इतने दुखी और उदास थे कि मुझे उनसे दिली हमदर्दी हुई और उनके घाव पर नमक छिड़कने का विचार ही लज्जास्पद जान पड़ा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('463dd2ff-db1d-4050-87fc-442cb6769bc2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हाँ, अब मुझे अपने ऊपर कुछ अभिमान हुआ और आत्मसम्मान भी बढ़ा। भाई साहब का वह रोब मुझ पर न रहा। आजादी से खेलकूद में शरीक होने लगा। दिल मजबूत था। अगर उन्होंने फिर मेरी फजीहत की, तो साफ कह दूँगा—'आपने अपना खून जलाकर कौन-सा तीर मार लिया। मैं तो खेलते-कूदते दरजे में अव्वल आ गया।'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4ff63c5c-962f-41c9-8bbe-ee196d1db26e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जुबान से यह हेकड़ी जताने का साहस न होने पर भी मेरे रंग-ढंग से साफ जाहिर होता था कि भाई साहब का वह आतंक मुझ पर नहीं था। भाई साहब ने इसे भाँप लिया—उनकी सहज बुद्धि बड़ी तीव्र थी और एक दिन जब मैं भोर का सारा समय गुल्ली-डंडे की भेंट करके ठीक भोजन के समय लौटा, तो भाई साहब ने मानो तलवार खींच ली और मुझ पर टूट पड़े...$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5f09e605-f453-49e1-924e-8a348feadd8f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$...'देखता हूँ, इस साल पास हो गए और दरजे में अव्वल आ गए, तो तुम्हें दिमाग हो गया है, मगर भाईजान, घमंड तो बड़े-बड़े का नहीं रहा, तुम्हारी क्या हस्ती है? इतिहास में रावण का हाल तो पढ़ा ही होगा। उसके चरित्र से तुमने कौन-सा उपदेश लिया? या यों ही पढ़ गए?'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0fd4ee54-1477-4031-b834-c44266ceaaaa', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नौ से साढ़े नौ तक इतिहास, फिर भोजन और स्कूल। साढ़े तीन बजे स्कूल से वापस होकर आधा घंटा आराम, चार से पाँच तक भूगोल, पाँच से छह तक ग्रामर, आधा घंटा हॉस्टल के सामने ही टहलना, साढ़े छह से सात तक अंग्रेजी कंपोजीशन, फिर भोजन करके आठ से नौ तक अनुवाद, नौ से दस तक हिंदी, दस से ग्यारह तक विविध-विषय, फिर विश्राम।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('366e61ff-767b-4b4d-9c59-ad3ad3c3f1d7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर टाइम-टेबिल बना लेना एक बात है, उस पर अमल करना दूसरी बात। पहले ही दिन उसकी अवहेलना शुरू हो जाती। मैदान की वह सुखद हरियाली, हवा के हलके-हलके झोंके, फुटबॉल की वह उछल-कूद, कबड्‌डी के वह दाँव-घात, वॉलीबॉल की वह तेजी और फुर्ती, मुझे अज्ञात और अनिवार्य रूप से खींच ले जाती और वहाँ जाते ही मैं सब कुछ भूल जाता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7557e361-af6b-449f-9032-813d7780e780', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह जानलेवा टाइम-टेबिल, वह आँखफोड़ पुस्तकें, किसी की याद न रहती और भाई साहब को नसीहत और फजीहत का अवसर मिल जाता। मैं उनके साये से भागता, उनकी आँखों से दूर रहने की चेष्टा करता, कमरे में इस तरह दबे पाँव आता कि उन्हें खबर न हो। उनकी नजर मेरी ओर उठी और मेरे प्राण निकले।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8290e614-36ad-4602-a7b3-33efe8cf646a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सालाना इम्तिहान हुआ। भाई साहब फेल हो गए, मैं पास हो गया और दरजे में प्रथम आया। मेरे और उनके बीच में केवल दो साल का अंतर रह गया। जी में आया, भाई साहब को आड़े हाथों लूँ—'आपकी वह घोर तपस्या कहाँ गई? मुझे देखिए, मजे से खेलता भी रहा और दरजे में अव्वल भी हूँ।' लेकिन वह इतने दुखी और उदास थे कि मुझे उनसे दिली हमदर्दी हुई और उनके घाव पर नमक छिड़कने का विचार ही लज्जास्पद जान पड़ा। हाँ, अब मुझे अपने ऊपर कुछ अभिमान हुआ और आत्मसम्मान भी बढ़ा। भाई साहब का वह रोब मुझ पर न रहा। आजादी से खेलकूद में शरीक होने लगा। दिल मजबूत था।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('93646107-c776-4909-a906-80ad55edeec3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जुबान से यह हेकड़ी जताने का साहस न होने पर भी मेरे रंग-ढंग से साफ जाहिर होता था कि भाई साहब का वह आतंक मुझ पर नहीं था। भाई साहब ने इसे भाँप लिया—उनकी सहज बुद्धि बड़ी तीव्र थी और एक दिन जब मैं भोर का सारा समय गुल्ली-डंडे की भेंट करके ठीक भोजन के समय लौटा, तो भाई साहब ने मानो तलवार खींच ली और मुझ पर टूट पड़े—'देखता हूँ, इस साल पास हो गए और दरजे में अव्वल आ गए, तो तुम्हें दिमाग हो गया है, मगर भाईजान, घमंड तो बड़े-बड़े का नहीं रहा, तुम्हारी क्या हस्ती है? इतिहास में रावण का हाल तो पढ़ा ही होगा। उसके चरित्र से तुमने कौन-सा उपदेश लिया? या यों ही पढ़ गए? महज इम्तिहान पास कर लेना कोई चीज नहीं, असली चीज है...'$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d2c7e05e-a5a4-4bca-8c5f-5034f0ca3c34', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुद्धि का विकास। जो कुछ पढ़ो, उसका अभिप्राय समझो। रावण भूमंडल का स्वामी था। ऐसे राजाओं को चक्रवर्ती कहते हैं। आजकल अंग्रेजों के राज्य का विस्तार बहुत बढ़ा हुआ है, पर इन्हें चक्रवर्ती नहीं कह सकते। संसार में अनेक राष्ट्र अंग्रेजों का आधिपत्य स्वीकार नहीं करते, बिल्कुल स्वाधीन हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('eff28336-eff7-4698-977e-0b7052610139', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रावण चक्रवर्ती राजा था, संसार के सभी महीप उसे कर देते थे। बड़े-बड़े देवता उसकी गुलामी करते थे। आग और पानी के देवता भी उसके दास थे, मगर उसका अंत क्या हुआ? घमंड ने उसका नाम-निशान तक मिटा दिया, कोई उसे एक चुल्लू पानी देने वाला भी न बचा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5030da7f-d485-402d-9d7c-7738b6aed94f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आदमी और जो कुकर्म चाहे करे, पर अभिमान न करे, इतराए नहीं। अभिमान किया और दीन-दुनिया दोनों से गया। शैतान का हाल भी पढ़ा ही होगा। उसे यह अभिमान हुआ था कि ईश्वर का उससे बढ़कर सच्चा भक्त कोई है ही नहीं। अंत में यह हुआ कि स्वर्ग से नर्क में ढकेल दिया गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cc3165f5-2da9-442e-856f-de24329d3e5c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शाह-ए-रूम ने भी एक बार अहंकार किया था। भीख मांग-मांगकर मर गया। तुमने तो अभी केवल एक दरजा पास किया है और अभी से तुम्हारा सिर फिर गया, तब तो तुम आगे पढ़ चुके। यह समझ लो कि तुम अपनी मेहनत से नहीं पास हुए, अंधे के हाथ बटेर लग गई।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('2a7fd8c0-4add-48b3-b14a-38bfcdeebbd5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर बटेर केवल एक बार हाथ लग सकती है, बार-बार नहीं लग सकती। कभी-कभी गुल्ली-डंडे में भी अंधा-चोट निशाना पड़ जाता है। इससे कोई सफल खिलाड़ी नहीं हो जाता। सफल खिलाड़ी वह है, जिसका कोई निशाना खाली न जाए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('42c688b1-972d-4de3-a497-63477ed7a88c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे फेल होने पर मत जाओ। मेरे दरजे में आओगे, तो दांतों पसीना आ जाएगा, जब अल्जेब्रा और जामेट्री के लोहे के चने चबाने पड़ेंगे और इंग्लिस्तान का इतिहास पढ़ना पड़ेगा। बादशाहों के नाम याद रखना आसान नहीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cb7be27a-3ebe-41b9-b2cf-788b881e0de1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आठ-आठ हेनरी हो गुजरे हैं। कौन-सा कांड किस हेनरी के समय में हुआ, क्या यह याद कर लेना आसान समझते हो? हेनरी सातवें की जगह हेनरी आठवां लिखा और सब नंबर गायब। सफाचट। सिफर भी न मिलेगा, सिफर भी। हो किस ख्याल में।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5be4362c-3677-4a3d-986e-68abfd8e46c2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दर्जनों तो जेम्स हुए हैं, दर्जनों विलियम, कोड़ियों चार्ल्स। दिमाग चक्कर खाने लगता है। आंधी रोग हो जाता है। इन अभागों को नाम भी न जुड़ते थे। एक ही नाम के पीछे दोयम, सोयम, चहारुम, पंचुम लगाते चले गए। मुझसे पूछते, तो दस लाख नाम बता देता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9361e55a-f6a8-4b84-a7d4-b76febbb9d49', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और जामेट्री तो बस, खुदा ही पनाह। अ ब ज की जगह अ ज ब लिख दिया और सारे नंबर कट गए। कोई इन निर्दयी मुमतहिनों से नहीं पूछता कि आखिर अ ब ज और अ ज ब में क्या फर्क है, और व्यर्थ की बात के लिए क्यों छात्रों का खून करते हो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9ecabb97-efd3-49b7-a469-afb8ebab365d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दाल-भात-रोटी खाई या भात-दाल-रोटी खाई, इसमें क्या रखा है, मगर इन परीक्षकों को क्या परवाह। वह तो वही देखते हैं जो पुस्तक में लिखा है। चाहते हैं कि लड़के अक्षर-अक्षर रट डालें। और इसी रटंत का नाम शिक्षा रख छोड़ा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('486e9ef4-3c1a-4d93-bc52-52df5dd93c93', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और आखिर इन बे-सिर-पैर की बातों के पढ़ने से फायदा? इस रेखा पर वह लंब गिरा दो, तो आधार लंब से दुगुना होगा। पूछिए, इससे प्रयोजन? दुगुना नहीं, चौगुना हो जाए, या आधा ही रहे, मेरी बला से, लेकिन परीक्षा में पास होना है, तो यह सब खुराफात याद करनी पड़ेगी।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('60cf40f3-0c35-452b-b8ed-b935b3bc7257', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुद्धि का विकास। जो कुछ पढ़ो, उसका अभिप्राय समझो। रावण भूमंडल का स्वामी था। ऐसे राजाओं को चक्रवर्ती कहते हैं। आजकल अंग्रेजों के राज्य का विस्तार बहुत बढ़ा हुआ है, पर इन्हें चक्रवर्ती नहीं कह सकते। संसार में अनेक राष्ट्र अंग्रेजों का आधिपत्य स्वीकार नहीं करते, बिल्कुल स्वाधीन हैं। रावण चक्रवर्ती राजा था, संसार के सभी महीप उसे कर देते थे। बड़े-बड़े देवता उसकी गुलामी करते थे। आग और पानी के देवता भी उसके दास थे, मगर उसका अंत क्या हुआ? घमंड ने उसका नाम-निशान तक मिटा दिया, कोई उसे एक चुल्लू पानी देने वाला भी न बचा। आदमी और जो कुकर्म चाहे करे, पर अभिमान न करे, इतराए नहीं। अभिमान किया और दीन-दुनिया दोनों से गया। शैतान का हाल भी पढ़ा ही होगा। उसे यह अभिमान हुआ था कि ईश्वर का उससे बढ़कर सच्चा भक्त कोई है ही नहीं। अंत में यह हुआ कि स्वर्ग से नर्क में ढकेल दिया गया। शाह-ए-रूम ने भी एक बार अहंकार किया था। भीख मांग-मांगकर मर गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('09672ff3-4182-4dc1-acb4-b1fc1c44e4a3', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं भी रोने लगा। अपने पास होने की खुशी आधी हो गई। मैं भी फेल हो गया होता, तो भाई साहब को इतना दुःख न होता, लेकिन विधि की बात कौन टाले! मेरे और भाई साहब के बीच में अब केवल एक दरजे का अंतर और रह गया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1de8e086-9532-4a79-acfc-9373b410c6a0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे मन में एक कुटिल भावना उदय हुई कि कहीं भाई साहब एक साल और फेल हो जाएँ, तो मैं उनके बराबर हो जाऊँ, फिर वह किस आधार पर मेरी फजीहत कर सकेंगे, लेकिन मैंने इस विचार को दिल से बलपूर्वक निकाल डाला। आखिर वह मुझे मेरे हित के विचार से ही तो डाँटते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('088d95af-aa04-4361-9bca-71ba79127b66', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे इस वक्त अप्रिय लगता है अवश्य, मगर यह शायद उनके उपदेशों का ही असर है कि मैं दनादन पास हो जाता हूँ और इतने अच्छे नंबरों से। अब भाई साहब बहुत कुछ नरम पड़ गए थे। कई बार मुझे डाँटने का अवसर पाकर भी उन्होंने धीरज से काम लिया।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('246d91d4-8fa2-4897-8d89-c0a8728acbe9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शायद अब वह खुद समझने लगे थे कि मुझे डाँटने का अधिकार उन्हें नहीं रहा, या रहा भी, तो बहुत कम। मेरी स्वच्छंदता भी बढ़ी। मैं उनकी सहिष्णुता का अनुचित लाभ उठाने लगा। मुझे कुछ ऐसी धारणा हुई कि मैं पास ही हो जाऊँगा, पढ़ूँ या न पढ़ूँ, मेरी तकदीर बलवान है, इसलिए भाई साहब के डर से जो थोड़ा-बहुत पढ़ लिया करता था, वह भी बंद हुआ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6e527ffb-91a6-4384-a562-ed8b227c8494', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे कनकाैए उड़ाने का नया शौक पैदा हो गया था और अब सारा समय पतंगबाज़ी की ही भेंट होता था, फिर भी मैं भाई साहब का अदब करता था और उनकी नजर बचाकर कनकाैए उड़ाता था। माँझा देना, कन्ने बाँधना, पतंग टूर्नामेंट की तैयारियाँ आदि समस्याएँ सब गुप्त रूप से हल की जाती थीं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0eeeb910-3e56-4d8f-807a-234901ae369c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं भाई साहब को यह संदेह न करने देना चाहता था कि उनका सम्मान और लिहाज मेरी नजरों में कम हो गया है। एक दिन संध्या समय, हॉस्टल से दूर मैं एक कनकाैआ लूटने बेतहाशा दौड़ा जा रहा था। आँखें आसमान की ओर थीं और मन उस आकाशगामी पथिक की ओर, जो मंद गति से झूमता पतन की ओर चला आ रहा था, मानो कोई आत्मा स्वर्ग से निकलकर विरक्त मन से नए संस्कार ग्रहण करने जा रही हो।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ea37133f-c824-432c-a78e-a963ec287507', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बालकों की पूरी सेना लट्ठे और झाड़दार बाँस लिए इनका स्वागत करने को दौड़ी आ रही थी। किसी को अपने आगे-पीछे की खबर न थी। सभी मानो उस पतंग के साथ ही आकाश में उड़ रहे थे, जहाँ सब कुछ समतल है, न मोटरकारें हैं, न ट्राम, न गाड़ियाँ।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9039d037-1c5b-4dc7-8590-906ea34f312b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सहसा भाई साहब से मेरी मुठभेड़ हो गई, जो शायद बाजार से लौट रहे थे। उन्होंने वहीं हाथ पकड़ लिया और उग्र भाव से बोले—इन बाजारी लौंडों के साथ धेले के कनकाैए के लिए दौड़ते तुम्हें शर्म नहीं आती?$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3b555616-b9c4-4b05-91fe-37dc2a0913fb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुम्हें इसका भी कुछ लिहाज नहीं कि अब नीची जमात में नहीं हो, बल्कि आठवीं जमात में आ गए हो और मुझसे केवल एक दरजा नीचे हो। आखिर आदमी को कुछ तो अपनी पोजीशन का खयाल रखना चाहिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('941ea68a-bf22-4ef2-a358-fcbc5e9187db', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक जमाना था कि लोग आठवाँ दरजा पास करके नायब तहसीलदार हो जाते थे। मैं कितने ही मिडिलचियों को जानता हूँ, जो आज अव्वल दरजे के डिप्टी मैजिस्ट्रेट या सुपरिंटेंडेंट हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cd7c4aff-837b-4a7e-99b9-f234b6a00ee6', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कितने ही आठवीं जमात वाले हमारे लीडर और समाचारपत्रों के संपादक हैं। बड़े-बड़े विद्वान उनकी मातहती$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8fe11594-a274-4c32-86f4-13ba28c4bab0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं भी रोने लगा। अपने पास होने की खुशी आधी हो गई। मैं भी फेल हो गया होता, तो भाई साहब को इतना दुःख न होता, लेकिन विधि की बात कौन टाले! ... मुझे कनकाैए उड़ाने का नया शौक पैदा हो गया था और अब सारा समय पतंगबाज़ी की ही भेंट होता था, फिर भी मैं भाई साहब का अदब करता था और उनकी नजर बचाकर कनकाैए उड़ाता था। ... सहसा भाई साहब से मेरी मुठभेड़ हो गई, जो शायद बाजार से लौट रहे थे। उन्होंने वहीं हाथ पकड़ लिया और उग्र भाव से बोले—इन बाजारी लौंडों के साथ धेले के कनकाैए के लिए दौड़ते तुम्हें शर्म नहीं आती? तुम्हें इसका भी कुछ लिहाज नहीं कि अब नीची जमात में नहीं हो, बल्कि आठवीं जमात में आ गए हो और मुझसे केवल एक दरजा नीचे हो। आखिर आदमी को कुछ तो अपनी पोजीशन का खयाल रखना चाहिए।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('aa7ccc6a-f1ea-4a0d-80d1-b81d70749e03', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं काम करते हैं और तुम उसी आठवें दरजे में आकर बाशारी लौंडों के साथ कनकाए के लिए दौड़ रहे हो। मुझे तुम्हारी इस कम अकली पर दुःख होता है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ace572f1-b617-4485-b38d-cc6aa852dcb0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुम ज़हीन हो, इसमें शक नहीं, लेकिन वह ज़ेहन किस काम का जो हमारे आत्मगौरव की हत्या कर डाले।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fd993990-37a6-49ee-8c7d-64367d4f8061', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुम अपने दिल में समझते होगे, मैं भाई साहब से महज़ एक दरजा नीचे हूँ और अब उन्हें मुझको कुछ कहने का हक नहीं है, लेकिन यह तुम्हारी गलती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ab5c0a5a-fcc4-494f-a5dd-a1e8aab8d0dc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं तुमसे पाँच साल बड़ा हूँ और चाहे आज तुम मेरी ही जमात में आ जाओ और परीक्षकों का यही हाल है, तो निस्संदेह अगले साल तुम मेरे समकक्ष हो जाओगे और शायद एक साल बाद मुझसे आगे भी निकल जाओ, लेकिन मुझमें और तुममें जो पाँच साल का अंतर है, उसे तुम क्या, खुदा भी नहीं मिटा सकता।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cb11c942-bac1-48d5-9cd4-b65d9eea4625', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं तुमसे पाँच साल बड़ा हूँ और हमेशा रहूँगा। मुझे दुनिया का और ज़िंदगी का जो तजुर्बा है, तुम उसकी बराबरी नहीं कर सकते, चाहे तुम एम.ए. और डी.फिल और डी.लिट् ही क्यों न हो जाओ। समझ किताबें पढ़ने से नहीं आती, दुनिया देखने से आती है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('204ca516-9183-4e50-9f7d-0605383e3bcf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारी अम्माँ ने कोई दरजा नहीं पास किया और दादा भी शायद पाँचवीं-छठी जमात के आगे नहीं गए, लेकिन हम दोनों चाहे सारी दुनिया की विद्या पढ़ लें, अम्माँ और दादा को हमें समझाने और सुधारने का अधिकार हमेशा रहेगा। केवल इसलिए नहीं कि वे हमारे जन्मदाता हैं, बल्कि इसलिए कि उन्हें दुनिया का हमसे ज़्यादा तजुर्बा है और रहेगा।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3eda16be-683e-42a4-98a5-d9f5f25964c1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अमेरिका में किस तरह की राज-व्यवस्था है, और आठवें हेनरी ने कितने ब्याह किए और आकाश में कितने नक्षत्र हैं, यह बातें चाहे उन्हें न मालूम हों, लेकिन हज़ारों ऐसी बातें हैं, जिनका ज्ञान उन्हें हमसे और तुमसे ज़्यादा है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('c364f76b-e6bf-451b-b043-bf35cf6e4f65', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$देव न करे, आज मैं बीमार हो जाऊँ, तो तुम्हारे हाथ-पाँव फूल जाएँगे। दादा को तार देने के सिवा तुम्हें और कुछ न सूझेगा, लेकिन तुम्हारी जगह दादा हों, तो किसी को तार न दें, न घबराएँ, न बदहवास हों। पहले खुद मर्ज़ पहचानकर इलाज करेंगे, उसमें सफल न हुए, तो किसी डॉक्टर को बुलाएँगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ffce1a7b-d0ed-4142-abf5-e5d9f7b1ad7c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बीमारी तो खैर बड़ी चीज़ है। हम-तुम तो इतना भी नहीं जानते कि महीने-भर का खर्च महीना-भर कैसे चले। जो कुछ दादा भेजते हैं, उसे हम बीस-बाईस तक खर्च कर डालते हैं और फिर पैसे-पैसे को मुहताज हो जाते हैं। नाश्ता बंद हो जाता है, धोबी और नाई से मुँह चुराने लगते हैं।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ce018b9c-6e3e-457c-943e-22e4b1287598', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन जितना आज हम और तुम खर्च कर रहे हैं, उसके आधे में दादा ने अपनी उम्र का बड़ा भाग इज़्ज़त और नेकनामी के साथ निभाया है और कुटुम्ब का पालन किया है जिसमें सब मिलकर नौ आदमी थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d49e444a-19a1-43f9-8c3e-750c988408d7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने हेडमास्टर साहब ही को देखो। एम.ए. हैं कि नहीं और यहाँ के एम.ए. नहीं, ऑक्सफोर्ड के। एक हज़ार रुपये पाते हैं; लेकिन उनके घर का इंतज़ाम कौन करता है? उनकी बूढ़ी माँ। हेडमास्टर साहब की डिग्री यहाँ बेकार हो गई। पहले खुद घर का इंतज़ाम करते थे। खर्च पूरा न पड़ता था। कर्जदार रहते थे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bbca5556-d972-4d3d-91d4-5ec4025aefc0', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब से उनकी माता जी ने प्रबंध अपने हाथ में ले लिया है, जैसे घर में लक्ष्मी आ गई है। तो भाईजान, यह गरूर दिल से निकाल डालो कि तुम मेरे समीप आ गए हो और अब स्वतंत्र हो। मेरे देखते तुम बेराह न चलने पाओगे।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('00272495-92aa-45de-b997-f2f2c8cab27b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुम यों न मानोगे तो मैं (थप्पड़ दिखाकर) इसका प्रयोग भी कर सकता हूँ। मैं जानता हूँ, तुम्हें मेरी बातें शहर लग रही हैं।--- मैं उनकी इस नई युक्ति से नतमस्तक हो गया। मुझे आज सचमुच अपनी लघुता का अनुभव हुआ और भाई साहब के प्रति मेरे मन में श्रद्धा उत्पन्न हुई। मैंने सजल आँखों से कहाµहरगिज नहीं। आप जो कुछ फरमा रहे हैं, वह बिल्कुल सच है और आपको उसके कहने का अधिकार है।$qbx$, 'comprehension'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
