  ('f9a8e31c-dfcb-4d4a-bc62-9a6e6a1c2fe5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह स्वभाव से बड़े अध्ययनशील थे। हरदम किताब खोले बैठे रहते और शायद दिमाग को आराम देने के लिए कभी कॉपी पर, किताब के हाशियों पर चिड़ियों, कुत्तों, बिल्लियों की तस्वीरें बनाया करते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('4f6de5f0-6691-41dc-b9d5-d50b9df81ab7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी-कभी एक ही नाम या शब्द या वाक्य दस-बीस बार लिख डालते। कभी एक शेर को बार-बार सुंदर अक्षरों में नकल करते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('230caced-8fe8-4631-8155-cb47c2ae60ac', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$कभी ऐसी शब्द-रचना करते, जिसमें न कोई अर्थ होता, न कोई सामंजस्य। मसलन एक बार उनकी कॉपी पर मैंने यह इबारत देखी—स्पेशल, अमीना, भाइयों-भाइयों, दरअसल, भाई-भाई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('de37fa22-e755-43fd-a392-f8ba1d637a39', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$राधेश्याम, श्रीयुत राधेश्याम, एक घंटे तक—इसके बाद एक आदमी का चेहरा बना हुआ था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('77592d1c-71cb-442f-9bd6-2255d6ef5e5f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैंने बहुत चेष्टा की कि इस पहेली का कोई अर्थ निकालूँ, लेकिन असफल रहा। और उनसे पूछने का साहस न हुआ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('05c25b82-1366-4183-8486-2008bfb9c7da', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह नौवीं जमात में थे, मैं पाँचवीं में।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('bbf93b98-0a60-4dd1-84e9-da91479c82f9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उनकी रचनाओं को समझना मेरे लिए छोटा मुँह बड़ी बात थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('c6da8fed-583f-4bc4-8d53-8248a1d79690', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा जी पढ़ने में बिल्कुल न लगता था। एक घंटा भी किताब लेकर बैठना पहाड़ था। मौका पाते ही हॉस्टल से निकलकर मैदान में आ जाता और कभी कंकड़ियाँ उछालता, कभी कागज़ की तितलियाँ उड़ाता और कहीं कोई साथी मिल गया, तो पूछना ही क्या। कभी चारदीवारी पर चढ़कर नीचे कूद रहे हैं। कभी फाटक पर सवार, उसे आगे-पीछे चलाते हुए मोटरकार का आनंद उठा रहे हैं$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 2, NULL),
  ('38bf776d-6df1-45df-9ecb-cf6758b7bd5a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन कमरे में आते ही भाई साहब का वह रुद्र-रूप देखकर प्राण सूख जाते। उनका पहला सवाल यह होता—'कहाँ थे?' हमेशा यही सवाल, इसी ध्वनि में हमेशा पूछा जाता था और इसका जवाब मेरे पास केवल मौन था। न जाने मेरे मुँह से यह बात क्यों न निकलती कि ज़रा बाहर खेल रहा था। मेरा मौन कह देता था कि मुझे अपना अपराध स्वीकार है$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7ae023b7-afdd-4624-afe7-a5d166822837', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और भाई साहब के लिए उसके सिवा और कोई इलाज न था कि स्नेह और रोष से मिले हुए शब्दों में मेरा सत्कार करें। 'इस तरह अंग्रेज़ी पढ़ोगे, तो ज़िंदगी-भर पढ़ते रहोगे और एक हर्फ़ न आएगा। अंग्रेज़ी पढ़ना कोई हँसी-खेल नहीं है कि जो चाहे, पढ़ ले, नहीं ऐरा-गैरा नत्थू-खैरा सभी अंग्रेज़ी के विद्वान हो जाते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('247ba60c-db64-4915-8352-fe1955ca41bc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$यहाँ रात-दिन आँखें फोड़नी पड़ती हैं और खून जलाना पड़ता है, तब कहीं यह विद्या आती है। और आती क्या है, हाँ कहने को आ जाती है। बड़े-बड़े विद्वान भी शुद्ध अंग्रेज़ी न लिख सकते, बोलना तो दूर रहा। और मैं कहता हूँ, तुम कितने घोंघा हो कि मुझे देखकर भी सबक नहीं लेते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0c5e400a-168f-4870-b42e-e82208138d59', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं कितनी मेहनत करता हूँ, यह तुम अपनी आँखों से देखते हो, अगर नहीं देखते, तो यह तुम्हारी आँखों का कसूर है, तुम्हारी बुद्धि का कसूर है। इतने मेले-तमाशे होते हैं, मुझे तुमने कभी देखने जाते देखा है? रोज़ ही क्रिकेट और हॉकी मैच होते हैं। मैं पास नहीं फटकता। हमेशा पढ़ता रहता हूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4dd46010-6e94-4498-b902-dc92ef9ea26a', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$उस पर भी एक-एक दरजे में दो-दो, तीन-तीन साल पड़ा रहता हूँ, फिर भी तुम कैसे आशा करते हो कि तुम यों खेल-कूद में वक़्त गँवाकर पास हो जाओगे? मुझे तो दो ही तीन साल लगते हैं, तुम उम्र-भर इसी दरजे में पड़े सड़ते रहोगे? अगर तुम्हें इस तरह उम्र गँवानी है, तो बेहतर है, घर चले जाओ और मज़े से गुल्ली-डंडा खेलो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('4ca9859e-cfd6-4e0d-8b3a-a43c29e34f26', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दादा की गाढ़ी कमाई के रुपये क्यों बर्बाद करते हो?' मैं यह लताड़ सुनकर आँसू बहाने लगता। जवाब ही क्या था। अपराध तो मैंने किया, लताड़ कौन सहे? भाई साहब उपदेश की कला में निपुण थे। ऐसी-ऐसी लगती बातें कहते, ऐसे-ऐसे सूक्ति-बाण चलाते कि मेरे जिगर के टुकड़े-टुकड़े हो जाते और हिम्मत टूट जाती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('95e6a5af-e102-4501-ab75-373d1fa70e65', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$इस तरह जान तोड़कर मेहनत करने की शक्ति मैं अपने में न पाता था और उस निराशा में ज़रा देर के लिए मैं सोचने लगता—'क्यों न घर चला जाऊँ? जो काम मेरे बूते के बाहर है, उसमें हाथ डालकर क्यों अपनी ज़िंदगी खराब करूँ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3e35476f-f23c-46bf-9854-19e36fa52431', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे अपना मूर्ख रहना मंजूर था, लेकिन उतनी मेहनत से मुझे तो चक्कर आ जाता था, लेकिन घंटे-दो घंटे के बाद निराशा के बादल फट जाते और मैं इरादा करता कि आगे से खूब जी लगाकर पढूँगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9b5e5440-6352-419a-9229-36f4a82896d7', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$चटपट एक टाइम-टेबिल बना डालता। बिना पहले से नक़्शा बनाए कोई स्कीम तैयार किए काम कैसे शुरू करूँ। टाइम-टेबिल में खेल-कूद की मद बिल्कुल उड़ जाती।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('66990a8d-db05-4ce3-984b-8d3d94678502', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$प्रातःकाल छह बजे उठना, मुँह-हाथ धो, नाश्ता कर, पढ़ने बैठ जाना। छह से आठ तक अंग्रेज़ी, आठ से नौ तक हिसाब$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('3ffadd6b-65ff-4821-84f5-64f5bfa14744', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरा जी पढ़ने में बिल्कुल न लगता था। एक घंटा भी किताब लेकर बैठना पहाड़ था। मौका पाते ही हॉस्टल से निकलकर मैदान में आ जाता और कभी कंकड़ियाँ उछालता, कभी कागज़ की तितलियाँ उड़ाता और कहीं कोई साथी मिल गया, तो पूछना ही क्या। कभी चारदीवारी पर चढ़कर नीचे कूद रहे हैं। कभी फाटक पर सवार, उसे आगे-पीछे चलाते हुए मोटरकार का आनंद उठा रहे हैं, लेकिन कमरे में आते ही भाई साहब का वह रुद्र-रूप देखकर प्राण सूख जाते।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b7bd98f1-52f6-41de-91e1-138957efd3d9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$नौ से साढ़े नौ तक इतिहास, फिर भोजन और स्कूल। साढ़े तीन बजे स्कूल से वापस होकर आधा घंटा आराम, चार से पाँच तक भूगोल, पाँच से छह तक ग्रामर, आधा घंटा हॉस्टल के सामने ही टहलना, साढ़े छह से सात तक अंग्रेजी कंपोजीशन, फिर भोजन करके आठ से नौ तक अनुवाद, नौ से दस तक हिंदी, दस से ग्यारह तक विविध-विषय, फिर विश्राम।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('077c92ea-3d55-45c5-9e98-89f3251d0d94', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर टाइम-टेबिल बना लेना एक बात है, उस पर अमल करना दूसरी बात। पहले ही दिन उसकी अवहेलना शुरू हो जाती। मैदान की वह सुखद हरियाली, हवा के हलके-हलके झोंके, फुटबॉल की वह उछल-कूद, कबड्‌डी के वह दाँव-घात, वॉलीबॉल की वह तेजी और फुर्ती, मुझे अज्ञात और अनिवार्य रूप से खींच ले जाती और वहाँ जाते ही मैं सब कुछ भूल जाता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('55287b40-2802-4c12-b233-024a89cdbac2', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$वह जानलेवा टाइम-टेबिल, वह आँखफोड़ पुस्तकें, किसी की याद न रहती और भाई साहब को नसीहत और फजीहत का अवसर मिल जाता। मैं उनके साये से भागता, उनकी आँखों से दूर रहने की चेष्टा करता, कमरे में इस तरह दबे पाँव आता कि उन्हें खबर न हो। उनकी नजर मेरी ओर उठी और मेरे प्राण निकले।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('361814db-0d7e-438d-b61e-9debc016934d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमेशा सिर पर एक नंगी तलवार-सी लटकती मालूम होती। फिर भी जैसे मौत और विपत्ति के बीच भी आदमी मोह और माया के बंधन में जकड़ा रहता है, मैं फटकार और घुड़कियाँ खाकर भी खेल-कूद का तिरस्कार न कर सकता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('801530cf-9f6d-4bce-9d97-f2144cbe1877', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$सालाना इम्तिहान हुआ। भाई साहब फेल हो गए, मैं पास हो गया और दरजे में प्रथम आया। मेरे और उनके बीच में केवल दो साल का अंतर रह गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('86c2ab2c-d08c-4a81-9b26-f638ff6bdd15', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जी में आया, भाई साहब को आड़े हाथों लूँ—'आपकी वह घोर तपस्या कहाँ गई? मुझे देखिए, मजे से खेलता भी रहा और दरजे में अव्वल भी हूँ।' लेकिन वह इतने दुखी और उदास थे कि मुझे उनसे दिली हमदर्दी हुई और उनके घाव पर नमक छिड़कने का विचार ही लज्जास्पद जान पड़ा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('02e13cdd-e683-4da5-9b84-78e4088c3955', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हाँ, अब मुझे अपने ऊपर कुछ अभिमान हुआ और आत्मसम्मान भी बढ़ा। भाई साहब का वह रोब मुझ पर न रहा। आजादी से खेलकूद में शरीक होने लगा। दिल मजबूत था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6568d0d4-346d-4d58-9a5c-314dafa6298c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अगर उन्होंने फिर मेरी फजीहत की, तो साफ कह दूँगा—'आपने अपना खून जलाकर कौन-सा तीर मार लिया। मैं तो खेलते-कूदते दरजे में अव्वल आ गया।'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('51ce1561-0e2b-4b29-ab80-a0eef6da9a69', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जुबान से यह हेकड़ी जताने का साहस न होने पर भी मेरे रंग-ढंग से साफ जाहिर होता था कि भाई साहब का वह आतंक मुझ पर नहीं था। भाई साहब ने इसे भाँप लिया—उनकी सहज बुद्धि बड़ी तीव्र थी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('16cc0003-9fb2-4eb3-8b7e-7577a052645f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और एक दिन जब मैं भोर का सारा समय गुल्ली-डंडे की भेंट करके ठीक भोजन के समय लौटा, तो भाई साहब ने मानो तलवार खींच ली और मुझ पर टूट पड़े—'देखता हूँ, इस साल पास हो गए और दरजे में अव्वल आ गए, तो तुम्हें दिमाग हो गया है...'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e92efca7-67bb-48a9-81ef-52c4b594a619', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'...मगर भाईजान, घमंड तो बड़े-बड़े का नहीं रहा, तुम्हारी क्या हस्ती है? इतिहास में रावण का हाल तो पढ़ा ही होगा। उसके चरित्र से तुमने कौन-सा उपदेश लिया? या यों ही पढ़ गए?'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('cfe2c94b-e885-41a4-9ab1-299c071f7e1c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$'महज इम्तिहान पास कर लेना कोई चीज नहीं, असली चीज है...'$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('9929fa83-1307-463d-9f59-626de6adce3f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुद्धि का विकास। जो कुछ पढ़ो, उसका अभिप्राय समझो। रावण भूमंडल का स्वामी था। ऐसे राजाओं को चक्रवर्ती कहते हैं। आजकल अंग्रेजों के राज्य का विस्तार बहुत बढ़ा हुआ है, पर इन्हें चक्रवर्ती नहीं कह सकते। संसार में अनेक राष्ट्र अंग्रेजों का आधिपत्य स्वीकार नहीं करते, बिल्कुल स्वाधीन हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('e8a60a90-e3bf-40cc-8bcd-5b67a90395eb', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$रावण चक्रवर्ती राजा था, संसार के सभी महीप उसे कर देते थे। बड़े-बड़े देवता उसकी गुलामी करते थे। आग और पानी के देवता भी उसके दास थे, मगर उसका अंत क्या हुआ? घमंड ने उसका नाम-निशान तक मिटा दिया, कोई उसे एक चुल्लू पानी देने वाला भी न बचा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7f853b20-893e-4146-94f4-f5d6469248d8', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आदमी और जो कुकर्म चाहे करे, पर अभिमान न करे, इतराए नहीं। अभिमान किया और दीन-दुनिया दोनों से गया। शैतान का हाल भी पढ़ा ही होगा। उसे यह अभिमान हुआ था कि ईश्वर का उससे बढ़कर सच्चा भक्त कोई है ही नहीं। अंत में यह हुआ कि स्वर्ग से नर्क में ढकेल दिया गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ac91ca94-930f-4b61-aba7-454ed6e8ebea', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शाह-ए-रूम ने भी एक बार अहंकार किया था। भीख मांग-मांगकर मर गया। तुमने तो अभी केवल एक दरजा पास किया है और अभी से तुम्हारा सिर फिर गया, तब तो तुम आगे पढ़ चुके। यह समझ लो कि तुम अपनी मेहनत से नहीं पास हुए, अंधे के हाथ बटेर लग गई।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('95228fac-4797-4d13-afb9-057c9d678e4f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मगर बटेर केवल एक बार हाथ लग सकती है, बार-बार नहीं लग सकती। कभी-कभी गुल्ली-डंडे में भी अंधा-चोट निशाना पड़ जाता है। इससे कोई सफल खिलाड़ी नहीं हो जाता। सफल खिलाड़ी वह है, जिसका कोई निशाना खाली न जाए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('fd00acfc-d57e-40b4-a2e3-9cf9257ef5fc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे फेल होने पर मत जाओ। मेरे दरजे में आओगे, तो दांतों पसीना आ जाएगा, जब अल्जेब्रा और जामेट्री के लोहे के चने चबाने पड़ेंगे और इंग्लिस्तान का इतिहास पढ़ना पड़ेगा। बादशाहों के नाम याद रखना आसान नहीं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('39cf37dd-aa4c-4d9f-b239-57cbfe3fda2e', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$आठ-आठ हेनरी हो गुजरे हैं। कौन-सा कांड किस हेनरी के समय में हुआ, क्या यह याद कर लेना आसान समझते हो? हेनरी सातवें की जगह हेनरी आठवां लिखा और सब नंबर गायब। सफाचट। सिफर भी न मिलेगा, सिफर भी। हो किस ख्याल में।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('af2e1a31-9484-4f39-9b2f-f34db990dc88', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दर्जनों तो जेम्स हुए हैं, दर्जनों विलियम, कोड़ियों चार्ल्स। दिमाग चक्कर खाने लगता है। आंधी रोग हो जाता है। इन अभागों को नाम भी न जुड़ते थे। एक ही नाम के पीछे दोयम, सोयम, चहारुम, पंचुम लगाते चले गए। मुझसे पूछते, तो दस लाख नाम बता देता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7f1d23bb-e205-4dfd-951d-c7bebed2a7e1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और जामेट्री तो बस, खुदा ही पनाह। अ ब ज की जगह अ ज ब लिख दिया और सारे नंबर कट गए। कोई इन निर्दयी मुमतहिनों से नहीं पूछता कि आखिर अ ब ज और अ ज ब में क्या फर्क है, और व्यर्थ की बात के लिए क्यों छात्रों का खून करते हो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('6ca8fb08-bc40-435d-9f2f-1d1b0c77b8bf', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$दाल-भात-रोटी खाई या भात-दाल-रोटी खाई, इसमें क्या रखा है, मगर इन परीक्षकों को क्या परवाह। वह तो वही देखते हैं जो पुस्तक में लिखा है। चाहते हैं कि लड़के अक्षर-अक्षर रट डालें। और इसी रटंत का नाम शिक्षा रख छोड़ा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b076ea32-0206-4abb-b09b-67ad0856fc2f', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$और आखिर इन बे-सिर-पैर की बातों के पढ़ने से फायदा? इस रेखा पर वह लंब गिरा दो, तो आधार लंब से दुगुना होगा। पूछिए, इससे प्रयोजन? दुगुना नहीं, चौगुना हो जाए, या आधा ही रहे, मेरी बला से, लेकिन परीक्षा में पास होना है, तो यह सब खुराफात याद करनी पड़ेगी।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('db647f04-e91d-4022-af11-b9cbec8a3330', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बुद्धि का विकास। जो कुछ पढ़ो, उसका अभिप्राय समझो। रावण भूमंडल का स्वामी था। ऐसे राजाओं को चक्रवर्ती कहते हैं। आजकल अंग्रेजों के राज्य का विस्तार बहुत बढ़ा हुआ है, पर इन्हें चक्रवर्ती नहीं कह सकते। संसार में अनेक राष्ट्र अंग्रेजों का आधिपत्य स्वीकार नहीं करते, बिल्कुल स्वाधीन हैं। रावण चक्रवर्ती राजा था, संसार के सभी महीप उसे कर देते थे। बड़े-बड़े देवता उसकी गुलामी करते थे। आग और पानी के देवता भी उसके दास थे, मगर उसका अंत क्या हुआ? घमंड ने उसका नाम-निशान तक मिटा दिया, कोई उसे एक चुल्लू पानी देने वाला भी न बचा। आदमी और जो कुकर्म चाहे करे, पर अभिमान न करे, इतराए नहीं। अभिमान किया और दीन-दुनिया दोनों से गया। शैतान का हाल भी पढ़ा ही होगा। उसे यह अभिमान हुआ था कि ईश्वर का उससे बढ़कर सच्चा भक्त कोई है ही नहीं। अंत में यह हुआ कि स्वर्ग से नर्क में ढकेल दिया गया। शाह-ए-रूम ने भी एक बार अहंकार किया था। भीख मांग-मांगकर मर गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('1a85526f-3843-49d1-9d5d-37fe5b03a20b', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं भी रोने लगा। अपने पास होने की खुशी आधी हो गई। मैं भी फेल हो गया होता, तो भाई साहब को इतना दुःख न होता, लेकिन विधि की बात कौन टाले! मेरे और भाई साहब के बीच में अब केवल एक दरजे का अंतर और रह गया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('48b5b116-65e1-4a79-9d52-3f6ec77fef9c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मेरे मन में एक कुटिल भावना उदय हुई कि कहीं भाई साहब एक साल और फेल हो जाएँ, तो मैं उनके बराबर हो जाऊँ, फिर वह किस आधार पर मेरी फजीहत कर सकेंगे, लेकिन मैंने इस विचार को दिल से बलपूर्वक निकाल डाला। आखिर वह मुझे मेरे हित के विचार से ही तो डाँटते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8b99e081-b74e-4809-a27a-e5d6d5e80b97', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे इस वक्त अप्रिय लगता है अवश्य, मगर यह शायद उनके उपदेशों का ही असर है कि मैं दनादन पास हो जाता हूँ और इतने अच्छे नंबरों से। अब भाई साहब बहुत कुछ नरम पड़ गए थे। कई बार मुझे डाँटने का अवसर पाकर भी उन्होंने धीरज से काम लिया।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('642c4480-9ec8-4b87-9926-643cf704f7a5', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$शायद अब वह खुद समझने लगे थे कि मुझे डाँटने का अधिकार उन्हें नहीं रहा, या रहा भी, तो बहुत कम। मेरी स्वच्छंदता भी बढ़ी। मैं उनकी सहिष्णुता का अनुचित लाभ उठाने लगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('918ffaa1-58c9-4a0c-8528-b78098a652fc', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे कुछ ऐसी धारणा हुई कि मैं पास ही हो जाऊँगा, पढ़ूँ या न पढ़ूँ, मेरी तकदीर बलवान है, इसलिए भाई साहब के डर से जो थोड़ा-बहुत पढ़ लिया करता था, वह भी बंद हुआ।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7c5bf559-81fc-4eff-94aa-28b702224f60', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मुझे कनकाैए उड़ाने का नया शौक पैदा हो गया था और अब सारा समय पतंगबाज़ी की ही भेंट होता था, फिर भी मैं भाई साहब का अदब करता था और उनकी नजर बचाकर कनकाैए उड़ाता था।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
