  ('77cdf505-749f-4b36-a38c-8703a80afa2c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक दिन संध्या समय, हॉस्टल से दूर मैं एक कनकाैआ लूटने बेतहाशा दौड़ा जा रहा था। आँखें आसमान की ओर थीं और मन उस आकाशगामी पथिक की ओर, जो मंद गति से झूमता पतन की ओर चला आ रहा था, मानो कोई आत्मा स्वर्ग से निकलकर विरक्त मन से नए संस्कार ग्रहण करने जा रही हो।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
