  ('d2aad168-59fa-4118-8691-3e7825d6e0ca', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुम्हें इसका भी कुछ लिहाज नहीं कि अब नीची जमात में नहीं हो, बल्कि आठवीं जमात में आ गए हो और मुझसे केवल एक दरजा नीचे हो। आखिर आदमी को कुछ तो अपनी पोजीशन का खयाल रखना चाहिए।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('bab03d59-a4ba-4387-9894-7e1832255add', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$एक जमाना था कि लोग आठवाँ दरजा पास करके नायब तहसीलदार हो जाते थे। मैं कितने ही मिडिलचियों को जानता हूँ, जो आज अव्वल दरजे के डिप्टी मैजिस्ट्रेट या सुपरिंटेंडेंट हैं। कितने ही आठवीं जमात वाले हमारे लीडर और समाचारपत्रों के संपादक हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('d5762c67-4a8f-41de-9849-332885c58133', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं काम करते हैं और तुम उसी आठवें दरजे में आकर बाशारी लौंडों के साथ कनकाए के लिए दौड़ रहे हो। मुझे तुम्हारी इस कम अकली पर दुःख होता है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('93e8207a-dad8-4705-bba8-b5ad88904152', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$तुम ज़हीन हो, इसमें शक नहीं, लेकिन वह ज़ेहन किस काम का जो हमारे आत्मगौरव की हत्या कर डाले।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
