  ('7fb04a85-9b62-452f-b7be-a7db80a5cefe', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं तुमसे पाँच साल बड़ा हूँ और चाहे आज तुम मेरी ही जमात में आ जाओ और परीक्षकों का यही हाल है, तो निस्संदेह अगले साल तुम मेरे समकक्ष हो जाओगे और शायद एक साल बाद मुझसे आगे भी निकल जाओ, लेकिन मुझमें और तुममें जो पाँच साल का अंतर है, उसे तुम क्या, खुदा भी नहीं मिटा सकता।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('b38cb2c0-d5db-422a-868a-40dbf6356d1c', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$मैं तुमसे पाँच साल बड़ा हूँ और हमेशा रहूँगा। मुझे दुनिया का और ज़िंदगी का जो तजुर्बा है, तुम उसकी बराबरी नहीं कर सकते, चाहे तुम एम.ए. और डी.फिल और डी.लिट् ही क्यों न हो जाओ। समझ किताबें पढ़ने से नहीं आती, दुनिया देखने से आती है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5a6681db-ac32-4866-a5f0-d3745eecda1d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$हमारी अम्माँ ने कोई दरजा नहीं पास किया और दादा भी शायद पाँचवीं-छठी जमात के आगे नहीं गए, लेकिन हम दोनों चाहे सारी दुनिया की विद्या पढ़ लें, अम्माँ और दादा को हमें समझाने और सुधारने का अधिकार हमेशा रहेगा। केवल इसलिए नहीं कि वे हमारे जन्मदाता हैं, बल्कि इसलिए कि उन्हें दुनिया का हमसे ज़्यादा तजुर्बा है और रहेगा।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('0512639e-d08a-45ec-b24b-a5d175eb1cb1', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अमेरिका में किस तरह की राज-व्यवस्था है, और आठवें हेनरी ने कितने ब्याह किए और आकाश में कितने नक्षत्र हैं, यह बातें चाहे उन्हें न मालूम हों, लेकिन हज़ारों ऐसी बातें हैं, जिनका ज्ञान उन्हें हमसे और तुमसे ज़्यादा है।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('abc4a0d0-ed58-4922-bd8d-bf2d44d40f4d', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$देव न करे, आज मैं बीमार हो जाऊँ, तो तुम्हारे हाथ-पाँव फूल जाएँगे। दादा को तार देने के सिवा तुम्हें और कुछ न सूझेगा, लेकिन तुम्हारी जगह दादा हों, तो किसी को तार न दें, न घबराएँ, न बदहवास हों। पहले खुद मर्ज़ पहचानकर इलाज करेंगे, उसमें सफल न हुए, तो किसी डॉक्टर को बुलाएँगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('8abc38da-9c0a-45db-a8e8-16f3e33dbbee', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$बीमारी तो खैर बड़ी चीज़ है। हम-तुम तो इतना भी नहीं जानते कि महीने-भर का खर्च महीना-भर कैसे चले। जो कुछ दादा भेजते हैं, उसे हम बीस-बाईस तक खर्च कर डालते हैं और फिर पैसे-पैसे को मुहताज हो जाते हैं। नाश्ता बंद हो जाता है, धोबी और नाई से मुँह चुराने लगते हैं।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('5606021e-bed2-44d7-a2e4-052caf6e3a03', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$लेकिन जितना आज हम और तुम खर्च कर रहे हैं, उसके आधे में दादा ने अपनी उम्र का बड़ा भाग इज़्ज़त और नेकनामी के साथ निभाया है और कुटुम्ब का पालन किया है जिसमें सब मिलकर नौ आदमी थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('ce03e567-90ae-467e-b60e-79f0e1ae95ba', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$अपने हेडमास्टर साहब ही को देखो। एम.ए. हैं कि नहीं और यहाँ के एम.ए. नहीं, ऑक्सफोर्ड के। एक हज़ार रुपये पाते हैं; लेकिन उनके घर का इंतज़ाम कौन करता है? उनकी बूढ़ी माँ। हेडमास्टर साहब की डिग्री यहाँ बेकार हो गई। पहले खुद घर का इंतज़ाम करते थे। खर्च पूरा न पड़ता था। कर्जदार रहते थे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
  ('7c5f4454-48a8-4a80-8803-216322db1dc9', '8af718c6-ca11-482b-9d6b-832f2b767928', 'c5439c1f-8e65-4e66-8c5e-9865b4eb1f8d', 'd8d04217-815a-49fc-88d2-442e0afe3be8', 'd9ec752e-e972-447c-b099-ccf502d554ab', '41e0a701-bdda-403b-bf4d-003aaffa605b', $qbx$जब से उनकी माता जी ने प्रबंध अपने हाथ में ले लिया है, जैसे घर में लक्ष्मी आ गई है। तो भाईजान, यह गरूर दिल से निकाल डालो कि तुम मेरे समीप आ गए हो और अब स्वतंत्र हो। मेरे देखते तुम बेराह न चलने पाओगे।$qbx$, 'long_answer'::question_type, NULL, NULL, 1, 5, ARRAY[]::text[], 'ai_xlsx_import_xlsx_2026-05-22T05-23-45-484Z', 'ba219b8a-c17f-46af-b642-be52f18c80ff', true, NULL, 3, NULL),
